	"""

	# 1. MISS CHECK
	var attack_roll = roll_attack(target)
	if attack_roll["is_miss"]:
		return {
			"result": "MISS",
			"damage": 0,
			"message": "Your attack misses!"
		}

	if not attack_roll["is_hit"]:
		return {
			"result": "MISS",
			"damage": 0,
			"message": "Your attack misses!"
		}

	# 2. RIPOSTE CHECK (Defender)
	if target.roll_parry():
		if target.roll_riposte():
			var riposte_damage = target.calculate_melee_damage(self)
			var riposte_crit = target.roll_crit()
			if riposte_crit:
				riposte_damage = target.calculate_melee_damage(self, true)
			riposte_damage = apply_ac_mitigation(riposte_damage, self)
			current_hp -= riposte_damage
			return {
				"result": "RIPOSTE",
				"damage": riposte_damage,
				"message": "Your opponent ripostes for " + str(riposte_damage) + " damage!"
			}

	# 3. PARRY CHECK (Defender)
	if target.roll_parry():
		return {
			"result": "PARRY",
			"damage": 0,
			"message": "Your attack is parried!"
		}

	# 4. BLOCK CHECK (Defender)
	if target.roll_block():
		return {
			"result": "BLOCK",
			"damage": 0,
			"message": "Your attack is blocked!"
		}

	# 5. DODGE CHECK (Defender)
	if target.roll_dodge():
		return {
			"result": "DODGE",
			"damage": 0,
			"message": "Your attack is dodged!"
		}

	# 6. HIT - CALCULATE DAMAGE
	var is_crit = roll_crit()
	var damage = calculate_melee_damage(target, is_crit)
	damage = apply_ac_mitigation(damage, target)

	target.current_hp -= damage

	var crit_message = " [CRITICAL]" if is_crit else ""
	return {
		"result": "HIT",
		"damage": damage,
		"is_crit": is_crit,
		"message": "You hit for " + str(damage) + " damage!" + crit_message
	}

# ================================================================================
# ⭐ DUAL-WIELD ATTACK SEQUENCE
# ================================================================================

func handle_combat() -> void:
	if Input.is_action_just_pressed("tab_target"):
		tab_cycle_target()
	if Input.is_action_just_pressed("attack_target"):
		autoattack_enabled = !autoattack_enabled
		if autoattack_enabled:
			if current_target == null or not is_instance_valid(current_target):
				tab_cycle_target()
			print("⚔️ Autoattack ON")
		else:
			print("⚔️ Autoattack OFF")
	if autoattack_enabled and current_target and attack_cooldown <= 0.0:
		attack_current_target()
	if Input.is_action_just_pressed("melee_attack") and attack_cooldown <= 0.0:
		perform_melee_attack()
	if Input.is_action_just_pressed("toggle_character_sheet"):
		toggle_character_sheet()


func tab_cycle_target() -> void:
	var monsters := get_tree().get_nodes_in_group("monsters")
	var valid: Array = []
	for m in monsters:
		if is_instance_valid(m) and m.get("current_state") != m.State.DEAD:
			valid.append(m)

	if valid.is_empty():
		current_target = null
		print("🎯 No targets available.")
		return

	valid.sort_custom(func(a, b):
		return global_position.distance_to(a.global_position) < global_position.distance_to(b.global_position)
	)

	if current_target == null or not is_instance_valid(current_target) or not valid.has(current_target):
		_target_idx = 0
	else:
		_target_idx = (valid.find(current_target) + 1) % valid.size()

	current_target = valid[_target_idx]
	var dist := global_position.distance_to(current_target.global_position)
	_set_target_frame(current_target)
	var msg := "🎯 %s [HP: %d/%d] (%.1fm)" % [
		current_target.get_monster_name(),
		current_target.current_health,
		current_target.max_health,
		dist
	]
	print(msg)
	GameLog.log_general(msg)


func attack_current_target() -> void:
	if not current_target or not is_instance_valid(current_target):
		current_target = null
		print("⚔️ No target selected. Press Tab to target.")
		return

	if current_target.get("current_state") == current_target.State.DEAD:
		print("⚔️ Target is already dead.")
		current_target = null
		return

	if attack_cooldown > 0.0:
		return

	var dist := global_position.distance_to(current_target.global_position)
	if dist > 3.0:
		print("⚔️ %s is out of range (%.1fm). Move closer!" % [current_target.get_monster_name(), dist])
		return

	attacking = true
	attack_cooldown = attack_cooldown_duration

	if "combat_node" in current_target and current_target.combat_node is CombatNode:
		var result = combat_node.resolve_attack(current_target.combat_node)
		if not combat_node.is_alive():
			die()
			return

# ===== COMBAT =====
func perform_attack() -> void:
	can_attack = false
	attack_timer = attack_cooldown

	if not player:
		return

	if "combat_node" in player and player.combat_node is CombatNode:
		var result = combat_node.resolve_attack(player.combat_node)
		# Sync our HP in case of riposte (resolve_attack modifies both sides directly)
		if not combat_node.is_alive():
			die()
			return
		if result["damage"] > 0:
			if player.has_method("apply_damage"):
				player.apply_damage(result["damage"])
			elif player.has_method("take_damage"):
				player.take_damage(result["damage"])
		if result["result"] != "MISS":
			GameLog.log_combat("%s → %s" % [get_monster_name().capitalize(), result.get("message", "")])
	elif player.has_method("take_damage"):
		player.take_damage(damage)
		GameLog.log_combat("%s hits you for %d damage!" % [get_monster_name().capitalize(), damage])

	if is_social:
		call_nearby_allies()

func apply_damage(amount: int, damage_type: String = "physical") -> void:
	if current_state == State.DEAD:
		return

	# Allow child classes to apply resistances/weaknesses before CombatNode takes over
	var modified_damage = modify_damage(amount, damage_type)
	combat_node.take_damage(modified_damage)

	print("DEBUG: %s hit for %d, HP: %d/%d" %

	if "combat_node" in current_target and current_target.combat_node is CombatNode:
		var result = combat_node.resolve_attack(current_target.combat_node)
		if not combat_node.is_alive():
			die()
			return
		if result["result"] != "MISS":
			GameLog.log_combat(result.get("message", ""))
		if not current_target.combat_node.is_alive():
			var kill_msg := "💀 %s defeated!" % current_target.get_monster_name()
			GameLog.log_combat(kill_msg)
			_set_target_frame(null)
			current_target = null
			autoattack_enabled = false
	else:
		var penalty := get_stat_penalty()
		var total_damage := int(combat_node.calculate_melee_damage(null, combat_node.roll_crit()) * penalty)
		if current_target.has_method("apply_damage"):
			current_target.apply_damage(total_damage, "physical")
			GameLog.log_combat("You hit %s for %d damage." % [current_target.get_monster_name(), total_damage])
		if not is_instance_valid(current_target) or current_target.current_health <= 0:
			GameLog.log_combat("💀 %s defeated!" % current_target.get_monster_name())
			_set_target_frame(null)
			current_target = null
			autoattack_enabled = false

	await get_tree().create_timer(0.3).timeout
	attacking = false


func perform_melee_attack() -> void:
	if attacking or dying:
