		"finger1": "", "finger2": "", "wrist1": "", "wrist2": "",
		"charm": "", "focus": "", "arms": "", "hands": "", "shoulders": "",
		"chest": "", "back": "", "waist": "", "legs": "", "feet": "",
		"trinket1": "", "trinket2": "", "primary": "", "secondary": "",
		"ranged": "", "ammo": ""
	}

